  ...props
}) => (
  <button
    type="button"
    style={{
      minHeight: "36px",
      display: "inline-flex",
      alignItems: "center",
      gap: "8px",
      padding: "6px 14px",
      borderRadius: "8px",
      fontSize: "0.875rem",
      fontWeight: 500,
      cursor: "pointer",
      border: selected
        ? "1px solid var(--sys-color-primary)"
        : "1px solid var(--sys-color-outline)",
      background: selected
        ? "var(--sys-color-surface-container-high)"
        : "transparent",
